import{_ as t,c as e,o as i,a3 as s}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/installation.md","filePath":"zh-CN/guide/installation.md","lastUpdated":1786612388000}'),r={name:"zh-CN/guide/installation.md"};function o(l,a,n,p,h,c){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><p>ClipboardxAI 提供 macOS 版本。</p><h2 id="下载方式" tabindex="-1">下载方式 <a class="header-anchor" href="#下载方式" aria-label="Permalink to &quot;下载方式&quot;">​</a></h2><h3 id="mac-app-store-推荐" tabindex="-1">Mac App Store（推荐） <a class="header-anchor" href="#mac-app-store-推荐" aria-label="Permalink to &quot;Mac App Store（推荐）&quot;">​</a></h3><ul><li><strong>下载</strong>：在 Mac App Store 中搜索 <strong>ClipboardxAI</strong>，或从<a href="/zh-CN/">首页</a>打开链接。</li><li>Mac App Store 版本提供自动更新，并与 macOS 无缝集成。</li></ul><blockquote><p><s>如果 Mac App Store 链接暂不可用，请使用下方 GitHub Releases 版本。</s></p></blockquote><h3 id="github-releases-备选-暂未提供" tabindex="-1"><s>GitHub Releases（备选）</s>（暂未提供） <a class="header-anchor" href="#github-releases-备选-暂未提供" aria-label="Permalink to &quot;~~GitHub Releases（备选）~~（暂未提供）&quot;">​</a></h3><p><s>你可以直接从 <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a> 下载最新版本。请注意，该版本不会收到自动更新。</s></p><h2 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to &quot;安装步骤&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>打开上方的下载链接，或在 Mac App Store 中搜索 &quot;ClipboardxAI&quot;。</li><li>点击 <strong>获取（Get）</strong> 下载该应用。</li><li>应用会自动安装——从 <strong>应用程序（Applications）</strong> 或 <strong>启动台（Launchpad）</strong> 中启动它。</li></ol><h3 id="github-releases" tabindex="-1"><s>GitHub Releases</s> <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;~~GitHub Releases~~&quot;">​</a></h3><ol><li><s>从 Releases 页面下载最新的 <code>.dmg</code> 文件。</s></li><li><s>双击下载的 <code>.dmg</code> 将其打开。</s></li><li><s>将 <code>ClipboardxAI.app</code> 图标拖入你的 <strong>应用程序（Applications）</strong> 文件夹。</s></li><li><s>推出挂载的镜像，并从 <strong>应用程序（Applications）</strong> 中打开该应用。</s></li></ol><p>如果 macOS 阻止打开该应用（Gatekeeper），请打开 <strong>系统设置 → 隐私与安全性（System Settings → Privacy &amp; Security）</strong>，点击 <strong>仍要打开（Open Anyway）</strong>，或右键点击应用并选择 <strong>打开（Open）</strong>。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><p>首次启动时，ClipboardxAI 会引导你完成简短的设置：</p><ul><li><strong>启用菜单栏图标</strong>，让应用常驻菜单栏。</li><li><strong>授予所需权限</strong>，用于在后台监控剪贴板（见<a href="/zh-CN/guide/permissions.html">权限说明</a>）。</li><li><em>（可选）</em> 如需 AI 操作，可在 <strong>设置 → AI（Settings → AI）</strong> 中连接一个云端 AI 提供商。</li></ul><p>在弹出提示时授予权限。你可以随时在 <strong>系统设置 → 隐私与安全性（System Settings → Privacy &amp; Security）</strong> 中进行更改。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><ul><li><strong>Mac App Store 版本</strong>：由 App Store 自动更新。</li><li><s><strong>GitHub Releases 版本</strong>：下载更新的版本，并替换 <code>Applications</code> 中的旧应用。</s></li></ul><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>要移除 ClipboardxAI：</p><ol><li>退出应用。</li><li>将 <code>ClipboardxAI.app</code> 从 <code>Applications</code> 拖入废纸篓。</li><li>（可选）移除本地数据：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Scripts/com.w3cub.clipboard</span></span></code></pre></div><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li><strong>macOS</strong>：Sonoma（14）或更高版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位）</li><li><strong>内存</strong>：最低 4 GB，推荐 8 GB</li><li><strong>存储空间</strong>：约 50 MB</li></ul><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><p>如果在安装过程中遇到问题：</p><ul><li><strong>macOS 阻止应用运行</strong>：打开 <strong>系统设置 → 隐私与安全性（System Settings → Privacy &amp; Security）</strong>，点击 <strong>仍要打开（Open Anyway）</strong>。</li><li><strong>公证（Notarization）警告</strong>：从 Mac App Store 下载已签名 / 已公证的版本。</li></ul><p>如需更多帮助，请参阅<a href="/zh-CN/guide/troubleshooting.html">故障排除指南</a>。</p>`,30)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
